<?php
/**
 * Single-file installer: upload this one file, open it in a browser, and it
 * unpacks the application next to itself, then hands over to the web installer.
 *
 * The application archive is appended after __halt_compiler() below. This file
 * is generated by tools/build; do not edit it by hand.
 *
 * Kept compatible with old PHP versions on purpose, so a server that is too
 * old shows a clear message instead of a syntax error.
 */

const SETUP_TITLE      = '{{TITLE}}';
const SETUP_VERSION    = '{{VERSION}}';
const SETUP_ROOT       = '{{ROOT}}';      // Top-level folder inside the archive; stripped when unpacking.
const SETUP_SHA256     = '{{SHA256}}';    // SHA-256 of the appended archive.
const SETUP_PHP        = '{{PHP}}';       // Minimum PHP version ("" when none).
const SETUP_EXTENSIONS = '{{EXTENSIONS}}';

@ini_set( 'display_errors', '0' );
header( 'Content-Type: text/html; charset=utf-8' );
header( 'Cache-Control: no-store' );
header( 'X-Robots-Tag: noindex' );

$setup_dir = __DIR__;
$problems  = setup_problems( $setup_dir );

if ( empty( $problems ) && 'POST' === ( isset( $_SERVER['REQUEST_METHOD'] ) ? $_SERVER['REQUEST_METHOD'] : 'GET' ) ) {
	$result = setup_unpack( $setup_dir );

	if ( true === $result ) {
		$self_deleted = @unlink( __FILE__ );
		setup_page( 'Files are in place', setup_done_html( $setup_dir, $self_deleted ) );
		exit;
	}

	$problems[] = $result;
}

setup_page( 'Install ' . SETUP_TITLE, setup_start_html( $setup_dir, $problems ) );
exit;

/*
|---------
| Checks
|---------
*/

/**
 * Everything that prevents unpacking, as plain-language messages.
 *
 * @param string $dir Folder the application is unpacked into.
 * @return string[]
 */
function setup_problems( $dir ) {
	$problems = array();

	if ( '' !== SETUP_PHP && version_compare( PHP_VERSION, SETUP_PHP, '<' ) ) {
		$problems[] = sprintf( '%s needs PHP %s or newer; this server runs PHP %s. Choose a newer PHP version in your hosting control panel, then reload this page.', SETUP_TITLE, SETUP_PHP, PHP_VERSION );
	}

	$missing = array();

	foreach ( array_unique( array_merge( array( 'zip' ), (array) SETUP_EXTENSIONS ) ) as $extension ) {
		if ( ! extension_loaded( $extension ) ) {
			$missing[] = $extension;
		}
	}

	if ( ! empty( $missing ) ) {
		$problems[] = sprintf( 'These PHP extensions are missing: %s. Enable them in your hosting control panel (often under "PHP extensions" or "Select PHP version"), then reload this page.', implode( ', ', $missing ) );
	}

	if ( ! is_writable( $dir ) ) {
		$problems[] = sprintf( 'This folder is not writable by the web server: %s. Allow writing to it (for example, permissions 755 owned by your account), then reload this page.', $dir );
	}

	$existing = array();

	foreach ( array( 'bootstrap.php', 'system', 'manifest.json' ) as $name ) {
		if ( file_exists( $dir . '/' . $name ) ) {
			$existing[] = $name;
		}
	}

	if ( ! empty( $existing ) ) {
		$problems[] = sprintf( 'This folder already contains an installation (%s). This file only installs into a folder without one; delete this file from the folder.', implode( ', ', $existing ) );
	}

	return $problems;
}

/*
|-----------
| Unpacking
|-----------
*/

/**
 * Unpack the appended archive into the folder.
 *
 * The archive is copied out of this file and checked against its SHA-256
 * first. Files are unpacked into a temporary folder, then moved into place,
 * so a failure leaves no half-unpacked application behind.
 *
 * @param string $dir Destination folder.
 * @return true|string True on success, otherwise a message.
 */
function setup_unpack( $dir ) {
	@set_time_limit( 0 );

	$token   = bin2hex( random_bytes( 6 ) );
	$archive = $dir . '/.setup-' . $token . '.zip';
	$staging = $dir . '/.setup-' . $token;

	$error = setup_copy_payload( $archive );

	if ( true !== $error ) {
		@unlink( $archive );
		return $error;
	}

	$error = setup_extract( $archive, $staging );
	@unlink( $archive );

	if ( true !== $error ) {
		setup_remove( $staging );
		return $error;
	}

	$entries = array_diff( (array) scandir( $staging ), array( '.', '..' ) );

	foreach ( $entries as $entry ) {
		// An existing .htaccess (hosts often add PHP version lines to it) is merged, not replaced.
		if ( '.htaccess' !== $entry && file_exists( $dir . '/' . $entry ) ) {
			setup_remove( $staging );
			return sprintf( '"%s" already exists in this folder. Move it away, then try again.', $entry );
		}
	}

	if ( in_array( '.htaccess', $entries, true ) && is_file( $dir . '/.htaccess' ) ) {
		$error = setup_merge_htaccess( $staging . '/.htaccess', $dir . '/.htaccess' );

		if ( true !== $error ) {
			setup_remove( $staging );
			return $error;
		}

		$entries = array_diff( $entries, array( '.htaccess' ) );
	}

	foreach ( $entries as $entry ) {
		if ( ! @rename( $staging . '/' . $entry, $dir . '/' . $entry ) ) {
			return sprintf( 'Could not move "%s" into place. Check that this folder is writable, delete what was already moved, then try again.', $entry );
		}
	}

	@rmdir( $staging );

	return true;
}

/**
 * Put the application's rules at the top of an existing .htaccess, keeping the rest.
 *
 * Hosts commonly keep their own lines in this file (for example cPanel's PHP
 * version handler); those must survive. The application's block comes first,
 * so its rewrite rules apply before any older ones.
 *
 * @param string $ours     The application's .htaccess (from the archive).
 * @param string $existing The .htaccess already in the folder.
 * @return true|string
 */
function setup_merge_htaccess( $ours, $existing ) {
	$current = @file_get_contents( $existing );
	$rules   = @file_get_contents( $ours );

	if ( false === $current || false === $rules ) {
		return 'Could not read the existing .htaccess file in this folder. Check its permissions, then try again.';
	}

	if ( false !== strpos( $current, '# BEGIN Smart License Server' ) ) {
		return true;
	}

	if ( false === @file_put_contents( $existing, rtrim( $rules ) . "\n\n" . $current ) ) {
		return 'Could not update the existing .htaccess file in this folder. Check that it is writable, then try again.';
	}

	@unlink( $ours );

	return true;
}

/**
 * Copy the archive appended to this file into its own file, verifying its hash.
 *
 * @param string $archive Destination path.
 * @return true|string
 */
function setup_copy_payload( $archive ) {
	$in  = @fopen( __FILE__, 'rb' );
	$out = @fopen( $archive, 'wb' );

	if ( ! $in || ! $out ) {
		return 'Could not read this file or write a temporary file next to it. Check that the folder is writable.';
	}

	fseek( $in, __COMPILER_HALT_OFFSET__ );
	$hash = hash_init( 'sha256' );

	while ( ! feof( $in ) ) {
		$chunk = fread( $in, 1048576 );

		if ( false === $chunk ) {
			break;
		}

		hash_update( $hash, $chunk );

		if ( false === fwrite( $out, $chunk ) ) {
			fclose( $in );
			fclose( $out );
			return 'Could not write the temporary archive. The disk may be full.';
		}
	}

	fclose( $in );
	fclose( $out );

	if ( ! hash_equals( SETUP_SHA256, hash_final( $hash ) ) ) {
		return 'This file is incomplete or damaged, usually from an interrupted upload. Upload it again in binary mode (FTP clients sometimes change files in "ASCII" mode), then reload this page.';
	}

	return true;
}

/**
 * Extract the archive, file by file, without its top-level folder.
 *
 * @param string $archive Archive path.
 * @param string $staging Folder to extract into.
 * @return true|string
 */
function setup_extract( $archive, $staging ) {
	$zip = new ZipArchive();

	if ( true !== $zip->open( $archive ) ) {
		return 'The archive inside this file could not be opened. Upload this file again, then reload this page.';
	}

	if ( ! @mkdir( $staging, 0755 ) ) {
		$zip->close();
		return 'Could not create a temporary folder. Check that this folder is writable.';
	}

	$prefix = SETUP_ROOT . '/';

	for ( $i = 0; $i < $zip->numFiles; $i++ ) {
		$name = (string) $zip->getNameIndex( $i );

		if ( 0 !== strpos( $name, $prefix ) ) {
			continue;
		}

		$relative = substr( $name, strlen( $prefix ) );

		if ( '' === $relative || '' === trim( $relative, '/' ) ) {
			continue;
		}

		// Never write outside the staging folder.
		if ( false !== strpos( $relative, '\\' ) || false !== strpos( $relative, ':' ) || in_array( '..', explode( '/', $relative ), true ) ) {
			$zip->close();
			return 'The archive contains an unsafe path and was not unpacked.';
		}

		$path = $staging . '/' . rtrim( $relative, '/' );

		if ( '/' === substr( $relative, -1 ) ) {
			if ( ! is_dir( $path ) && ! @mkdir( $path, 0755, true ) ) {
				$zip->close();
				return 'Could not create the folder ' . $relative . '.';
			}
			continue;
		}

		if ( ! is_dir( dirname( $path ) ) && ! @mkdir( dirname( $path ), 0755, true ) ) {
			$zip->close();
			return 'Could not create the folder for ' . $relative . '.';
		}

		$stream = $zip->getStream( $name );
		$target = @fopen( $path, 'wb' );

		if ( ! $stream || ! $target ) {
			$zip->close();
			return 'Could not write ' . $relative . '. The disk may be full.';
		}

		stream_copy_to_stream( $stream, $target );
		fclose( $stream );
		fclose( $target );

		// Unix permissions stored in the archive (e.g. the executable CLI entry).
		$opsys = 0;
		$attr  = 0;

		if ( $zip->getExternalAttributesIndex( $i, $opsys, $attr ) && ZipArchive::OPSYS_UNIX === $opsys && ( $attr >> 16 ) & 0777 ) {
			@chmod( $path, ( $attr >> 16 ) & 0777 );
		}
	}

	$zip->close();

	return true;
}

/**
 * Remove a folder tree.
 *
 * @param string $path Folder.
 * @return void
 */
function setup_remove( $path ) {
	if ( is_link( $path ) || is_file( $path ) ) {
		@unlink( $path );
		return;
	}

	if ( ! is_dir( $path ) ) {
		return;
	}

	foreach ( array_diff( (array) scandir( $path ), array( '.', '..' ) ) as $entry ) {
		setup_remove( $path . '/' . $entry );
	}

	@rmdir( $path );
}

/*
|-------
| Pages
|-------
*/

/**
 * Escape text for HTML.
 *
 * @param string $text Text.
 * @return string
 */
function setup_e( $text ) {
	return htmlspecialchars( (string) $text, ENT_QUOTES, 'UTF-8' );
}

/**
 * The first page: what will happen, or what prevents it.
 *
 * @param string   $dir      Destination folder.
 * @param string[] $problems Problems found.
 * @return string
 */
function setup_start_html( $dir, $problems ) {
	if ( ! empty( $problems ) ) {
		$items = '';

		foreach ( $problems as $problem ) {
			$items .= '<li>' . setup_e( $problem ) . '</li>';
		}

		return '<p>The files cannot be unpacked yet:</p><ul class="problems">' . $items . '</ul>';
	}

	return '<p>This unpacks ' . setup_e( SETUP_TITLE . ' ' . SETUP_VERSION ) . ' into this folder:</p>'
		. '<p><code>' . setup_e( $dir ) . '</code></p>'
		. '<p>It takes a few seconds. Afterwards this file deletes itself, and you continue with the setup in your browser.</p>'
		. '<form method="post"><button type="submit">Unpack the files</button></form>';
}

/**
 * The final page: where to go next.
 *
 * @param string $dir          Destination folder.
 * @param bool   $self_deleted Whether this file was deleted.
 * @return string
 */
function setup_done_html( $dir, $self_deleted ) {
	$html = '<p>' . setup_e( SETUP_TITLE . ' ' . SETUP_VERSION ) . ' was unpacked into <code>' . setup_e( $dir ) . '</code>.</p>';

	if ( setup_reads_htaccess() ) {
		// The .htaccess shipped in this folder sends every request into public/,
		// so the site works from here and nothing else in the folder is reachable.
		$html .= '<h2>Next: run the installer</h2>'
			. '<p><a href="./?install">Open the installer</a> and follow the steps.</p>'
			. '<p class="hint">Recommended when you can: set your domain&rsquo;s document root to <code>' . setup_e( $dir . '/public' ) . '</code>. '
			. 'Until then, the <code>.htaccess</code> file in this folder keeps everything outside <code>public</code> out of reach; do not delete it.</p>';
	} else {
		$html .= '<h2>Before you continue: change the document root</h2>'
			. '<p class="warning">This web server does not read <code>.htaccess</code> files, so everything in this folder can be downloaded from the web, including the settings file the installer creates. Do not run the installer yet.</p>'
			. '<p>Set your domain&rsquo;s document root to:</p>'
			. '<p><code>' . setup_e( $dir . '/public' ) . '</code></p>'
			. '<p>Then open <code>https://your-domain/install</code>. Ready-made configurations for nginx and Caddy are in the <code>server</code> folder.</p>';
	}

	if ( ! $self_deleted ) {
		$html .= '<p class="warning">This file could not delete itself. Delete <code>' . setup_e( basename( __FILE__ ) ) . '</code> from the folder now.</p>';
	}

	return $html;
}

/**
 * Whether the web server applies .htaccess files (Apache, LiteSpeed).
 *
 * Unknown servers count as not reading them, so the page never claims a
 * protection that may not exist.
 *
 * @return bool
 */
function setup_reads_htaccess() {
	$software = strtolower( isset( $_SERVER['SERVER_SOFTWARE'] ) ? (string) $_SERVER['SERVER_SOFTWARE'] : '' );

	return false !== strpos( $software, 'apache' ) || false !== strpos( $software, 'litespeed' );
}

/**
 * Print a complete page.
 *
 * @param string $title Title.
 * @param string $body  Body HTML.
 * @return void
 */
function setup_page( $title, $body ) {
	echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">'
		. '<meta name="robots" content="noindex"><title>' . setup_e( $title ) . '</title><style>'
		. 'body{font:16px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif;background:#f4f5f7;color:#1d2330;margin:0;padding:48px 16px}'
		. 'main{max-width:640px;margin:0 auto;background:#fff;border:1px solid #dfe2e8;border-radius:10px;padding:32px}'
		. 'h1{font-size:1.45rem;margin:0 0 4px}h2{font-size:1.05rem;margin:28px 0 8px}.version{color:#5b6475;margin:0 0 24px}'
		. 'code{background:#f0f2f5;padding:2px 6px;border-radius:4px;word-break:break-all}'
		. 'button{font:inherit;font-weight:600;background:#2457d6;color:#fff;border:0;border-radius:6px;padding:10px 20px;cursor:pointer}'
		. 'button:hover{background:#1b46b0}.problems li{margin-bottom:8px}.hint{color:#5b6475}.warning{color:#9a3412}'
		. '@media (prefers-color-scheme:dark){body{background:#14171c;color:#e4e7ec}main{background:#1c2027;border-color:#2e333d}'
		. 'code{background:#262b34}.version,.hint{color:#9aa3b2}.warning{color:#fb923c}}'
		. '</style></head><body><main><h1>' . setup_e( $title ) . '</h1><p class="version">' . setup_e( SETUP_TITLE . ' ' . SETUP_VERSION ) . '</p>'
		. $body . '</main></body></html>';
}

__halt_compiler();